class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        List<ListNode> nodes = new ArrayList<>();
        for (ListNode c = head; c != null; c = c.next) nodes.add(c);
        int target = nodes.size() - n;
        if (target == 0) return head.next;                        // removing the head
        nodes.get(target - 1).next = nodes.get(target).next;      // skip over the target
        return head;
    }
}

